# Player guidance follows the current implementation. \n becomes a localized paragraph break.
function Tutorial-Translations {
    $t=[ordered]@{
        'tutorial.alone_mechanical.title'=@('孤独机械 · 教程书','Alone Mechanical · Field Guide')
        'tutorial.alone_mechanical.tooltip'=@('右键打开教程书','Right-click to open the field guide')
        'tutorial.alone_mechanical.directory'=@('教学目录','Contents')
        'tutorial.alone_mechanical.previous'=@('上一页','Back')
        'tutorial.alone_mechanical.next'=@('下一页','Next')
        'tutorial.alone_mechanical.close'=@('关闭 · Esc','Close · Esc')
        'tutorial.alone_mechanical.page'=@('%s / %s 页','Page %s / %s')
    }
    $chapters=[ordered]@{
        start=@('入门与工具','Getting started',
            '本书说明当前机器的构建、供电和运输规则，具体配方以当前世界的JEI或数据包为准。\n\n所有本模组物品和方块默认只提示按住Shift；按住后显示功能、参数、操作与限制。\n\n工程锤：依次右键两个对角点，端点也计入范围。Shift+右键方块或空气取消。构建失败保留第一点，修好再选第二点。\n\n扳手：普通右键机器端口切换通道；Shift+右键管道支臂切换模式，普通右键查看模式。\n\n教程书可右键空气或方块打开，主手空置时可用副手书。左侧选择章节，滚轮、左右键或PageUp/PageDown翻页，Esc关闭。阅读不消耗物品。',
            'This guide explains building, power and transport. Check current JEI or data packs for recipes.\n\nEvery mod item and block shows only a Shift hint by default. Hold Shift for its function, parameters, controls and limits.\n\nHammer: click opposite corners, including both endpoints. Shift-right-click a block or air to cancel. Failed builds retain the first corner for retrying.\n\nWrench: normal-click ports to cycle channels. Shift-click pipe arms to change modes; normal-click inspects them.\n\nUse the book in the air or on blocks, including the offhand with an empty main hand. Select chapters on the left, scroll or use arrows/PageUp/PageDown to turn pages. Esc closes it. Reading consumes nothing.')
        grid=@('电网与连线','Power grid',
            '电网核心占一格，负责储能；信号杆与供电桩占1×1×5，拆任意段移除整杆。这些节点不发电。\n\n右键节点GUI，点击开始连线，再右键目标。重复连接会断线；选点期间潜行右键节点取消。无核心时也能先连线，但不能把两个核心合入一个网络。\n\n当前信号杆/核心连线最远%s格，供电桩最远%s格，取两端较短限制，距离包含高度差。\n\n只有供电桩给机器供电，以底座为中心覆盖水平%s×%s、上下各%s格，按机器中心核心位置判断。信号杆只转接线路。\n\n兼容FE设备向电网核心输入电力。创造电源需要设备提取，不会自行推送FE。机器先充入自身电池，断网后可用余电；只有已加载的连通路径能供电。',
            'A one-block power core stores FE; poles and pylons occupy 1×1×5. Breaking any segment removes the pole. These nodes do not generate power.\n\nOpen a node GUI, start wiring, then click the target. Repeat a link to disconnect; sneak-click a node while selecting to cancel. Coreless networks are allowed, but two cores cannot share a grid.\n\nCurrent link limits: poles/cores %s blocks, pylons %s blocks. The shorter endpoint limit applies, including height differences.\n\nOnly pylons supply machines. Coverage is %s×%s horizontally and %s blocks above/below the base, checked at the machine center core. Poles only relay links.\n\nFeed FE into the core using compatible equipment. Creative power requires extraction and never pushes FE itself. Machines charge batteries and may use stored energy while disconnected. Only loaded paths supply power.')
        structure=@('多方块构建','Multiblock building',
            '完整长方体外表面，每轴至少3格、当前上限%s格，三边可不同。机器外壳、玻璃、线圈、矩阵、端口、仓储均可用作合法外表面。\n\n外表面恰好一个通用机器控制器，内部中心恰好一个对应核心。偶数轴取较低的中心格。其他内部可为空气或合法机器部件。\n\n所有机器至少一个能量矩阵。处理矩阵不是成型必需品。各类机器的仓储列数和介质要求见后续章节。\n\n通用端口必须紧贴仓储列的上端或下端，自动按相邻仓储选择接口。同列所有端口必须完全同一通道，输入1与输入2也不能共用列。仓储列不能跨出选区，机器不能重叠。\n\n先设置端口通道，再用工程锤选两个对角点检测。失败会报告原因和坐标。结构损坏停止加工，修复后重新锤定；不会靠等待自动首次成型。',
            'Complete a cuboid surface, each axis at least 3 and up to %s blocks; axes may differ. Casings, glass, coils, matrices, ports and stores are valid surface parts.\n\nExactly one controller belongs on the surface and one matching core at the interior center. Even axes use the lower center block. Other interior spaces may contain air or valid parts.\n\nEvery machine needs an energy matrix. Processing matrices are optional. See the following chapters for storage profiles.\n\nAttach universal ports directly above/below a column; they adapt to its storage. All its ports must use the same channel; even Input 1 and Input 2 need separate columns. Columns cannot cross the selection and machines cannot overlap.\n\nConfigure channels before hammering opposite corners. Failures report causes and positions. Damage stops processing; repair and validate again. Initial formation requires the hammer.')
        machines=@('物品加工机器','Item processing',
            '粉碎机：粉碎核心，至少两个独立物品仓列。输入1、输出1各至少27槽，使用对应物品端口。默认粗铁/粗铜/粗金每个产出2个对应粉末，基础100 tick、20 FE/t。\n\n电弧炉：熔炼核心，物品仓要求与粉碎机相同。使用当前已加载的熔炼配方，消耗FE而非燃料。不是所有粉末都自动可熔炼。\n\n合金冶炼机：合金核心，恰好三列。输入1为主料物品仓，输入2为物品仓/流体罐/气体罐，输出1为物品仓。实际材料、辅料、比例与耗能由配方定义。\n\n预留材料不代表已有配方。用JEI查询当前配方；无匹配配方时不加工、不消耗原料，但电池仍可充电。空手普通右键成型结构任意部件打开GUI。',
            'Crusher: crusher core, separate Input 1 and Output 1 vault columns with at least 27 slots each and matching item ports. Default raw iron/copper/gold recipes yield two matching dusts per raw item, at 100 ticks and 20 FE/t.\n\nArc furnace: smelting core and the same vault requirements. Uses loaded furnace recipes with FE instead of fuel; powder smelting is not automatic.\n\nAlloy smelter: alloy core and exactly three columns. Item Input 1 is the main material; Input 2 may be an item vault, fluid tank or gas tank; Output 1 is an item vault. Recipes define ingredients, ratios and costs.\n\nReserved materials do not imply recipes. Inspect JEI. Without a matching recipe, processing and input consumption stop, but batteries may charge. Empty-hand right-click any formed part for its GUI.')
        reactors=@('双相反应釜','Biphasic reactors',
            '反应核心，恰好三列独立仓储：输入1、输入2、输出1。每列配通用端口，紧贴列顶部或底部，接口自动适配仓储。\n\n介质组合决定九种模式：\n物品+流体→流体：溶出制液\n物品+流体→物品：溶解析晶\n流体+气体→流体：液相捕收\n流体+气体→气体：液相生气\n物品+气体→物品：气固相炼\n物品+气体→气体：固转气化\n流体+流体→流体：液相合制\n气体+气体→气体：气相化合\n物品+物品→物品：固相熔合\n\n不同介质的输入可交换通道，配方按介质对应；同种介质时按配方指定通道放料。成型提示和GUI显示模式。反应配方由数据包提供，不会自动反应任意材料。',
            'Use a reaction core and exactly three independent columns: Input 1, Input 2 and Output 1, with universal ports directly above/below them.\n\nResource types select nine profiles:\nItem + fluid → fluid: Dissolution\nItem + fluid → item: Crystallization\nFluid + gas → fluid: Liquid capture\nFluid + gas → gas: Gas evolution\nItem + gas → item: Gas-solid refining\nItem + gas → gas: Solid gasification\nFluid + fluid → fluid: Liquid-phase synthesis\nGas + gas → gas: Gas-phase synthesis\nItem + item → item: Solid fusion\n\nDifferent input resource types may swap channels; recipes map them by type. For equal types, use recipe-specified channels. Formation messages and the GUI show the profile. Data packs provide reactions; arbitrary resources never react automatically.')
        conversion=@('气液转化机','Gas/liquid conversion',
            '转化核心，恰好一列流体罐和一列气体罐，不需要物品仓。每列配对应端口，至少一个能量矩阵。\n\n两列分别设输入1和输出1，不使用输入2/输出2。气体输入、流体输出为液化；流体输入、气体输出为气化。先设端口，再工程锤构建。\n\n成型后GUI可切换方向，同步切换端口并清空当前进度。切换前检查原料与缓存，避免中断加工批次。\n\n物质关系、比例、时长、耗能由配方定义。当前没有自带转化配方，不会把任意液体当气体；添加对应数据包后在JEI查看。',
            'Use a conversion core with exactly one fluid tank column and one gas tank column, matching ports and at least one energy matrix. No vault is required.\n\nUse Input 1 and Output 1 only. Gas input/fluid output selects liquefaction; fluid input/gas output selects vaporization. Configure ports before hammering the structure.\n\nThe GUI can switch direction, update ports and reset current progress. Check resources and stored contents before interrupting a running batch.\n\nRecipes define mappings, ratios, duration and energy. No conversions ship by default; fluids and gases remain separate resources. Provide matching data packs and inspect them in JEI.')
        storage=@('仓储与端口','Stores and ports',
            '通用储罐可存流体或气体，按内容和记忆的介质识别，清空后可换相；同列不能混装。旧流体罐/气体罐为兼容方块。通用端口根据相邻仓储自动选择接口。\n\n同类仓储只竖向合列，不横向合并。每段物品仓增加27槽，流体/气体罐增加16000 mB。不同介质内容不能混合。\n\n机器内仓储只存储，自动化通过对应端口。端口直接接列顶部或底部，侧面不分配机器库存。\n\n扳手普通右键端口循环输入1/输入2/输出1/输出2。输入只接收，输出只提取。同列所有端口必须完全同一通道，不允许输入/输出共列或输入1/输入2共列。\n\n普通粉碎机/电弧炉可汇总同通道多列真实库存；反应釜、转化机、合金机必须遵守各自严格的列数要求。GUI翻页查看所有物品仓槽位。\n\n独立仓储右键打开专用GUI；机器内潜行右键仓储打开仓储GUI，普通右键打开机器GUI。潜行手持流体容器右键流体罐可装入/取出液体。仓储本身不切换通道。',
            'Universal tanks accept fluid or gas, identified by stored contents and remembered phase. Empty a column before switching; types cannot mix. Old fluid/gas tanks remain compatible. Universal ports adapt to adjacent storage.\n\nMatching stores merge vertically only. Each vault adds 27 slots; each fluid/gas tank adds 16000 mB. Incompatible contents cannot mix.\n\nInside machines, stores only hold resources; ports handle automation directly above/below columns. Side ports do not assign inventory.\n\nNormal wrench-click cycles Input 1/2 and Output 1/2. Inputs accept; outputs extract. One column must use exactly one channel, including separate columns for Input 1 and Input 2.\n\nCrushers/arc furnaces may aggregate several columns per channel. Reactors, converters and alloy smelters require exact profiles. GUI paging exposes all physical vault slots.\n\nRight-click standalone stores for their GUI. In formed machines, sneak-click opens the store view; normal-click opens the machine. Sneak-use fluid containers on fluid tanks to fill/drain. Stores do not switch channels themselves.')
        pipes=@('管道与端面','Pipes and faces',
            '管道一至五级依次为赤铜、殷钢、共振、超导、量子；物品、流体、气体管道共用这套等级名称。六面连接兼容设备。介质网络不混接，只处理已加载区块。\n\n物品五级速率为4/16/64/128/256个/秒；流体与气体为4000/16000/64000/128000/256000 mB/秒。分支共享主干预算，混级路径受最慢段限制，可用出口均分、满仓跳过。\n\n流体/气体每段缓存1000 mB，与等级无关，堵塞暂存、存档保留、恢复后按速率送出。物品管道无常规库存，只在异常拒收时暂存退不回的物品。\n\n普通接收和输出，不主动抽取。Shift+扳手右键支臂循环普通→拉取→推送→断开。蓝色拉取环主动抽取，橙色推送环输出，断开停止该面传输。\n\n例：输出仓→物品输出1端口→管道→目标输入1端口→输入仓。源端设拉取，目标端普通或推送。通用端口自动适配仓储介质，机器内仓储本体不提供自动化接口。',
            'Pipe tiers 1–5 are Red Copper, Invar, Resonant, Superconducting and Quantum, shared by item, fluid and gas pipes. Use the matching pipe kind with compatible devices. Six-sided resource networks stay separate and only use loaded chunks.\n\nItem rates are 4/16/64/128/256 items/s. Fluid/gas rates are 4000/16000/64000/128000/256000 mB/s. Branches share trunk budgets; mixed paths use the slowest segment. Available exits split fairly and full targets are skipped.\n\nEach fluid/gas segment buffers 1000 mB, independent of tier. Blocked contents persist and resume at tier speed. Item pipes have no regular inventory, only escrow for unexpected rejected transfers that cannot be refunded.\n\nNormal receives/sends without extraction. Shift-wrench-click cycles Normal → Pull → Push → None. Blue Pull collars extract; orange Push collars send; None disconnects that face.\n\nExample: output vault → item Output 1 port → pipes → target Input 1 port → input vault. Use Pull at the source and Normal/Push at the destination. Universal ports adapt to storage; formed stores do not expose automation directly.')
        upgrades=@('线圈与矩阵','Coils and matrices',
            '能量线圈每个从基础耗能减20%%，加法叠加，最多%s个生效。效率线圈每个加15%%速度、10%%耗能倍率，无额外数量上限。每份每tick最终最低1 FE。\n\n能量矩阵至少1个，同时作为成型机器FE输入端。当前基础电池为%s FE，实际容量=基础容量×(1+矩阵数)。1个矩阵即基础的2倍。\n\n处理矩阵每个使并行上限翻倍，最多%s个有效、%s份并行。没有处理矩阵也能单份加工。每轮按原料和输出空间选定批次，本轮固定；原料、产物、耗能按份数增加，周期不变。\n\n强化外壳保护成型机器免受爆炸；结构玻璃透光并连接边框。线圈和矩阵可放在合法外表面或内部。',
            'Energy coils subtract 20%% of base cost each, additively, up to %s. Efficiency coils add 15%% speed and 10%% energy multiplier each, without a count cap. Each recipe costs at least 1 FE per active tick.\n\nAt least one energy matrix is required and accepts FE after formation. Current base battery: %s FE. Actual capacity = base × (1 + matrix count); one matrix gives twice the base.\n\nProcessing matrices double the parallel limit, up to %s effective and %s recipes. No matrix still allows single recipes. Each cycle locks a batch based on inputs/output room; resources, products and energy scale with it, while duration is unchanged.\n\nReinforced casing protects formed machines from explosions. Glass transmits light and joins frames. Coils/matrices may be on the valid shell or inside.')
        help=@('GUI与排查','GUI and troubleshooting',
            '不成型：读锤子的原因与坐标，检查尺寸、中心核心、唯一外表面控制器、至少1能量矩阵、完整外壳和各机型仓储要求。端口先设通道，紧贴匹配列上/下端。\n\n库存不对：每段物品仓27槽，上下堆叠累加；库存来自真实仓储。各物品通道独立翻页，Shift搬运使用完整输入通道。\n\n不输送：核对介质、通道、源端拉取、目标空间与区块加载。机器内仓储只存储，需端口连接。\n\n不加工：查看状态、原料、输出空间和FE。供电桩覆盖机器核心；矩阵也可接收FE。切换配方或转化方向会重置进度。\n\n无配方：查JEI，不凭材料名称推测用途。反应釜/气液转化需对应数据包配方，电弧炉只适配已加载熔炼配方。按住Shift查看物品功能与参数。',
            'Cannot form: read hammer causes/positions. Check size, center core, one surface controller, energy matrix, complete shell and storage profile. Configure matching ports directly above/below columns.\n\nWrong inventory: each vault adds 27 real slots. Item channels page independently; Shift-moving uses the entire input channel.\n\nNo transfer: check resource type, channels, Pull at the source, destination room and loaded chunks. Formed stores require ports.\n\nNo processing: inspect status, inputs, output room and FE. Pylons cover the machine core; formed matrices also accept FE. Recipe or direction changes reset progress.\n\nNo recipe: inspect JEI rather than guessing from material names. Reactors/converters need data packs; arc furnaces adapt loaded smelting recipes. Hold Shift for item functions and parameters.')
    }
    $chapters['builds']=@('机器搭建示例','Machine build examples',
        '快速演示：管理员可执行 `/AloneMechanical build +结构`，也可手动按模板搭建。所有示例都使用完整外壳、中心核心、控制器和能量矩阵，仓储列的顶部或底部紧贴通用端口。\n\n粉碎机：粉碎核心；输入1物品仓、输出1物品仓。\n电弧炉：熔炼核心上方放煅烧组件；仓储布局同粉碎机。\n锻压机：工业核心上方放锻压组件；仓储布局同粉碎机。\n塑形机：工业核心上方放塑形组件；输入1和输出1各一列物品仓。\n灌注机：工业核心上方放灌注组件；输入1物品、输入2流体或气体、输出1物品。\n合金冶炼机：熔炼核心上方放合金组件；输入1主料、输入2辅料、输出1物品。\n双相反应釜：反应核心上方放化合组件；输入1、输入2、输出1三列。\n分离机：反应核心上方放分解组件；输入1、输出1、输出2三列。\n气液转化机：转换核心；输入1和输出1使用相反介质。\n锅炉：锅炉核心；四列储罐依次为水、热载体、蒸汽、冷却载体。\n涡轮发电机：涡轮核心；横向能量矩阵和连续转子必须同高度同一条X/Z轴，输入1接蒸汽储罐。\n屠杀器、养殖塔、收割塔、驱逐塔：工业核心上方放对应组件，固定3×3平面，输出1物品仓；养殖塔另加输入1食物仓。\n基础光能机、夜光机和热能机直接放置，顶部光能板需露天；电动泵直接放置在水或岩浆源上方，能量矩阵是完整外壳内放矩阵并用工程锤成型。\n\n工程锤选两个对角点后检查结构，缺少部件时聊天栏显示具体原因。',
        'Quick demo: administrators can run `/AloneMechanical build +structure`, or build from the templates below. Every example uses a complete shell, center core, controller, energy matrix and universal ports directly above or below storage columns.\n\nCrusher: crusher core; item Input 1 and Output 1 vaults.\nArc furnace: smelting core plus calcination component; same vault layout.\nForging press: industrial core plus forging component; same vault layout.\nForming machine: industrial core plus forming component; item Input 1 and Output 1.\nInfuser: industrial core plus infusion component; item Input 1, fluid or gas Input 2, item Output 1.\nAlloy smelter: smelting core plus alloy component; main Input 1, additive Input 2, item Output 1.\nBiphasic reactor: reaction core plus combination component; Input 1, Input 2 and Output 1.\nSeparator: reaction core plus decomposition component; Input 1, Output 1 and Output 2.\nGas/liquid converter: conversion core; Input 1 and Output 1 use opposite phases.\nBoiler: boiler core; four tanks for water, heat carrier, steam and cooled carrier.\nTurbine generator: turbine core; horizontal matrix and continuous rotors share one X/Z line, with steam on Input 1.\nSlaughterhouse, breeding tower, harvest tower and repeller tower: industrial core plus matching component, fixed 3×3 footprint and item Output 1; breeding also needs food Input 1.\nBasic solar, luminous solar and thermal generators are placed directly with open sky above the panels; the electric pump is placed directly above a water or lava source; an energy matrix is a casing-and-matrix cuboid formed with the hammer.\n\nHammer two opposite corners to validate; missing parts report a specific chat reason.')
    foreach($entry in $chapters.GetEnumerator()){
        $t["tutorial.alone_mechanical.$($entry.Key).title"]=@($entry.Value[0],$entry.Value[1])
        $t["tutorial.alone_mechanical.$($entry.Key).body"]=@($entry.Value[2].Replace('\n',[string][char]10),$entry.Value[3].Replace('\n',[string][char]10))
    }
    $t['tutorial.alone_mechanical.machines.body'][0]+="`n`n炼钢：2 铁粉＋1 碳粉 → 2 钢锭。主料铁粉放输入1，辅料碳粉放输入2。基础周期200 tick（10秒），40 FE/t。煤或木炭在粉碎机中制成碳粉（1→1），铁粉由粗铁粉碎获得。合金冶炼机支持线圈和处理矩阵，每个增加1个并行位及15%%耗能倍率，无额外数量上限。"
    $t['tutorial.alone_mechanical.machines.body'][1]+="`n`nSteel: 2 iron dust + 1 carbon dust → 2 steel ingots. Put iron dust in Input 1 and carbon dust in Input 2. Base cycle: 200 ticks (10 seconds), 40 FE/t. Crush coal or charcoal for carbon dust (1 to 1), and raw iron for iron dust. Alloy smelters support coils and processing matrices, each adding one parallel slot and 15%% energy multiplier without a count cap."
    $t['tutorial.alone_mechanical.separation.title']=@('单入双出分离机','Separators')
    $t['tutorial.alone_mechanical.separation.body']=@(
        '分离核心，恰好三列独立仓储：输入1、输出1、输出2，不使用输入2。每列配上下相邻的通用端口，另需完整外壳、唯一控制器及至少一个能量矩阵。

输入可为物品、流体或气体；双输出有六种介质组合：物品+物品、物品+流体、物品+气体、流体+流体、流体+气体、气体+气体，合计18种分离模式。

例如物品分成物品+流体是固液分离；流体分成气体+气体是电解；气体分成两种气体是气相分馏。机器名称取决于仓储通道的介质，不是换不同核心。

两路输出都要有空间，且配方必须匹配当前模式。具体原料、两种产物、比例、时长与耗能以当前JEI或数据包为准；不能把任意资源自动拆分。',
        'Use a separation core and exactly three independent columns: Input 1, Output 1 and Output 2. No Input 2. Attach universal ports above/below columns, with a complete shell, one controller and an energy matrix.

Inputs may be items, fluids or gases. Six output pairs are supported: item+item, item+fluid, item+gas, fluid+fluid, fluid+gas and gas+gas, giving 18 profiles.

Examples: item to item+fluid is solid/liquid separation; fluid to gas+gas is electrolysis; gas to gas+gas is gas fractionation. Storage channel resource types select the machine profile, not a different core.

Both outputs need room and a recipe must match the profile. JEI/data packs define inputs, both products, ratios, duration and energy; arbitrary resources cannot be split automatically.')
    $t['tutorial.alone_mechanical.grid.body'][0]+="`n`n生存发电：基础光能机白天发电，夜光机昼夜持续发电，顶部均需露天；面板随太阳/月亮转动。热能机燃烧煤炭、木炭、煤炭块或一次性电池。三种发电机放在电网核心旁即可供电，也可向相邻FE输入端送电。右键查看缓存、当前功率和剩余燃烧时间。`n`n初/中/高级电池的功率与时长依次为1/2/4倍初级。高级高功率变种为1.5倍功率、0.7倍时长；高级长续航变种为1倍功率、1.5倍时长。满电暂停燃烧，耗尽不返回空电池；合成查JEI，当前参数按Shift查看。"
    $t['tutorial.alone_mechanical.grid.body'][1]+="`n`nSurvival generation: basic solar works by day; luminous solar works day and night. Both require open sky and track the sun/moon. Thermal generators burn coal, charcoal, coal blocks or disposable batteries. Place a generator beside the grid core or another FE input. Right-click for stored FE, output and remaining burn time.`n`nBasic/intermediate/advanced batteries use 1/2/4 times the basic power and duration. Advanced high-power uses x1.5 output and x0.7 duration; advanced long-life uses x1 output and x1.5 duration. Burning pauses at full charge. Depleted batteries return no empty item. Check crafting in JEI and current settings with Shift."
    return $t
}
